insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5610f6bd-c181-505e-95dc-cc7a44e3b92a', 'Populations that are separated stop interbreeding and diverge gradually during speciation [1]; there is no clear point at which they become separate species, and if they never meet we cannot test whether they can interbreed [1].', 'Populations that are separated stop interbreeding and diverge gradually during speciation [1]; there is no clear point at which they become separate species, and if they never meet we cannot test whether they can interbreed [1].', '[{"text": "Marking point 1", "any": ["gradual", "diverge", "speciation", "continuous"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["do not meet", "not interbreed", "isolated", "cannot test", "no clear point"], "all": [], "marks": 1}]'::jsonb, 'Populations that are separated stop interbreeding and diverge gradually during speciation [1]; there is no clear point at which they become separate species, and if they never meet we cannot test whether they can interbreed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
