insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ecc3ef28-42d8-5046-84d4-13b6030c2770', 'Horses and donkeys can interbreed to produce mules [1], but mules are sterile, so the parents do not produce fertile offspring and are separate species [1].', 'Horses and donkeys can interbreed to produce mules [1], but mules are sterile, so the parents do not produce fertile offspring and are separate species [1].', '[{"text": "Marking point 1", "any": ["mule", "offspring", "hybrid"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sterile", "infertile", "not fertile"], "all": [], "marks": 1}]'::jsonb, 'Horses and donkeys can interbreed to produce mules [1], but mules are sterile, so the parents do not produce fertile offspring and are separate species [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
