insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('07030f1d-0287-5432-8c03-75321bc91433', 'They are evolutionarily distinct, with few close relatives, so losing them loses a large amount of unique evolutionary history [1]; and they are globally endangered, so they are at high risk of extinction [1].', 'They are evolutionarily distinct, with few close relatives, so losing them loses a large amount of unique evolutionary history [1]; and they are globally endangered, so they are at high risk of extinction [1].', '[{"text": "Marking point 1", "any": ["distinct", "few relatives", "unique"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["endangered", "threatened", "risk"], "all": [], "marks": 1}]'::jsonb, 'They are evolutionarily distinct, with few close relatives, so losing them loses a large amount of unique evolutionary history [1]; and they are globally endangered, so they are at high risk of extinction [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
