insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('dd86f59d-121a-5d89-82b6-60b5328698d9', 'Advantage: protects species from immediate threats and allows captive breeding / seed banks as a backup [1]; limitations: small captive populations lose genetic diversity and natural behaviour, and release may fail if the habitat is still lost [1]; it is expensive and does not address the causes of decline [1].', 'Advantage: protects species from immediate threats and allows captive breeding / seed banks as a backup [1]; limitations: small captive populations lose genetic diversity and natural behaviour, and release may fail if the habitat is still lost [1]; it is expensive and does not address the causes of decline [1].', '[{"text": "Marking point 1", "any": ["protect", "safe", "breeding", "seed bank", "backup"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["habitat", "natural behaviour", "genetic diversity", "small population", "release"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["expensive", "cost", "not address", "cause"], "all": [], "marks": 1}]'::jsonb, 'Advantage: protects species from immediate threats and allows captive breeding / seed banks as a backup [1]; limitations: small captive populations lose genetic diversity and natural behaviour, and release may fail if the habitat is still lost [1]; it is expensive and does not address the causes of decline [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
