insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('477a74e6-fae4-5ed8-98ae-b0b9290ac5f9', 'Lay a line across a gradient (e.g. from woodland edge into a field) [1]; place quadrats at regular intervals and record abundance/percentage cover of the species [1]; measure the abiotic factor (e.g. light, soil moisture) at each quadrat and compare [1].', 'Lay a line across a gradient (e.g. from woodland edge into a field) [1]; place quadrats at regular intervals and record abundance/percentage cover of the species [1]; measure the abiotic factor (e.g. light, soil moisture) at each quadrat and compare [1].', '[{"text": "Marking point 1", "any": ["line", "transect", "tape"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["quadrat", "intervals", "regular"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["measure", "light", "soil", "moisture", "ph", "abiotic"], "all": [], "marks": 1}]'::jsonb, 'Lay a line across a gradient (e.g. from woodland edge into a field) [1]; place quadrats at regular intervals and record abundance/percentage cover of the species [1]; measure the abiotic factor (e.g. light, soil moisture) at each quadrat and compare [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
