insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('62249ffe-dfde-5aa9-9c92-97af77dde4d3', 'In artificial selection humans deliberately choose which individuals breed, whereas in natural selection the environment determines survival and reproduction [1]; both act on heritable variation and change allele frequencies over generations [1].', 'In artificial selection humans deliberately choose which individuals breed, whereas in natural selection the environment determines survival and reproduction [1]; both act on heritable variation and change allele frequencies over generations [1].', '[{"text": "Marking point 1", "any": ["human", "deliberate", "chosen"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["environment", "survival", "nature"], "all": [], "marks": 1}]'::jsonb, 'In artificial selection humans deliberately choose which individuals breed, whereas in natural selection the environment determines survival and reproduction [1]; both act on heritable variation and change allele frequencies over generations [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
