insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f821fb87-6154-522c-9e58-17d894f516f5', 'q² = 0.16 so q = 0.4 and p = 0.6 [1]; 2pq = 2 × 0.6 × 0.4 = 0.48 (48%) [1].', 'q² = 0.16 so q = 0.4 and p = 0.6 [1]; 2pq = 2 × 0.6 × 0.4 = 0.48 (48%) [1].', '[{"text": "Marking point 1", "any": ["0.4", "q = 0.4", "√0.16"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.48", "48"], "all": [], "marks": 1}]'::jsonb, 'q² = 0.16 so q = 0.4 and p = 0.6 [1]; 2pq = 2 × 0.6 × 0.4 = 0.48 (48%) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
