insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5e53e178-384c-5ad2-b9fb-cb14c2268ed2', 'Domesticated species have changed greatly from their wild ancestors through deliberate selection (e.g. many cabbage varieties from wild cabbage) [1]; this shows species can change in a short time, so natural selection over long periods could produce evolution [1].', 'Domesticated species have changed greatly from their wild ancestors through deliberate selection (e.g. many cabbage varieties from wild cabbage) [1]; this shows species can change in a short time, so natural selection over long periods could produce evolution [1].', '[{"text": "Marking point 1", "any": ["change", "differ", "varieties", "breeds"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["short time", "few generations", "selection", "natural selection"], "all": [], "marks": 1}]'::jsonb, 'Domesticated species have changed greatly from their wild ancestors through deliberate selection (e.g. many cabbage varieties from wild cabbage) [1]; this shows species can change in a short time, so natural selection over long periods could produce evolution [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
